const root = $input.first().json || {};
function locOf(u){ if(!u) return null; if(typeof u === 'string') return u; if(u.loc){ return (typeof u.loc === 'string') ? u.loc : (u.loc._ || null); } return null; }
let urls = [];
if (root.urlset && root.urlset.url) {
  const arr = Array.isArray(root.urlset.url) ? root.urlset.url : [root.urlset.url];
  urls = arr.map(locOf).filter(Boolean);
} else if (root.sitemapindex && root.sitemapindex.sitemap) {
  const arr = Array.isArray(root.sitemapindex.sitemap) ? root.sitemapindex.sitemap : [root.sitemapindex.sitemap];
  urls = arr.map(locOf).filter(Boolean);
}
const seen = {};
const out = [];
for (let i=0;i<urls.length;i++){ const u = urls[i]; if(u && !seen[u]){ seen[u] = 1; out.push({ json: { url: u } }); } }
return out;

const cfg = $('Config').first().json || {};
const siteUrl = cfg.siteUrl || '';
let siteHost = siteUrl;
try { siteHost = siteUrl.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '') || siteUrl; } catch (e) {}

const pages = $('Limit Pages').all().map(function(x){ return x.json.url; });
const crawls = $input.all();

const gsc = $('GSC Queries').first().json || {};
const gscRows = gsc.rows || [];
const qByPage = {};
for (let i=0;i<gscRows.length;i++){
  const r = gscRows[i]; const keys = r.keys || [];
  const page = keys[0]; const query = keys[1];
  if(!page) continue;
  if(!qByPage[page]) qByPage[page] = [];
  qByPage[page].push({ q: query, imp: r.impressions || 0 });
}
function topQueries(page){
  const list = qByPage[page] || [];
  list.sort(function(a,b){ return b.imp - a.imp; });
  return list.slice(0,5).map(function(x){ return x.q; }).filter(Boolean);
}

function canon(u){ return (u||'').split('#')[0].split('?')[0].replace(/\/$/, ''); }

function normalize(href){
  if(!href) return null;
  href = ('' + href).trim();
  if(!href) return null;
  const low = href.toLowerCase();
  if(href.charAt(0) === '#' || low.indexOf('mailto:') === 0 || low.indexOf('tel:') === 0 || low.indexOf('javascript:') === 0) return null;
  let abs = href;
  if(href.indexOf('//') === 0){ abs = 'https:' + href; }
  else if(href.charAt(0) === '/'){ abs = 'https://' + siteHost + href; }
  else if(href.indexOf('http') !== 0){ abs = 'https://' + siteHost + '/' + href; }
  const bare = abs.replace(/^https?:\/\//, '').replace(/^www\./, '');
  if(bare.indexOf(siteHost) !== 0) return null;
  return abs.split('#')[0].split('?')[0];
}

function extractLinks(html){
  if(!html || typeof html !== 'string') return [];
  const out = [];
  const re = /href\s*=\s*["']([^"']+)["']/gi;
  let m;
  while((m = re.exec(html)) !== null){ const n = normalize(m[1]); if(n) out.push(n); }
  return out;
}

const inbound = {};
const existing = {};
const pageInfo = [];
for (let i=0;i<pages.length;i++){
  const url = pages[i];
  const html = (crawls[i] && crawls[i].json) ? crawls[i].json.data : '';
  const links = extractLinks(html);
  const srcC = canon(url);
  const seen = {};
  for (let j=0;j<links.length;j++){
    const tgtC = canon(links[j]);
    if(tgtC === srcC) continue;
    existing[srcC + '|' + tgtC] = true;
    if(!seen[tgtC]){ seen[tgtC] = 1; inbound[tgtC] = (inbound[tgtC] || 0) + 1; }
  }
  pageInfo.push({ url: url, canon: srcC, topQueries: topQueries(url), outbound: links.length });
}
for (let i=0;i<pageInfo.length;i++){ const p = pageInfo[i]; p.inbound = inbound[p.canon] || 0; p.isOrphan = (p.inbound === 0); }

const validUrls = pageInfo.map(function(p){ return p.url; });
const orphans = pageInfo.filter(function(p){ return p.isOrphan; }).map(function(p){ return p.url; });
const llmPages = pageInfo.map(function(p){ return { url: p.url, topQueries: p.topQueries, isOrphan: p.isOrphan }; });

return [{ json: {
  siteHost: siteHost,
  pages: pageInfo,
  llmPages: llmPages,
  orphans: orphans,
  validUrls: validUrls,
  existingLinks: Object.keys(existing),
  minConfidence: (cfg.minConfidence !== undefined ? cfg.minConfidence : 0.6),
  maxPerPage: (cfg.maxSuggestionsPerPage !== undefined ? cfg.maxSuggestionsPerPage : 3)
} }];

const map = $('Build Map + Orphans').first().json || {};
function canon(u){ return (u||'').split('#')[0].split('?')[0].replace(/\/$/, ''); }
const validSet = {};
(map.validUrls || []).forEach(function(u){ validSet[canon(u)] = true; });
const existing = {};
(map.existingLinks || []).forEach(function(k){ existing[k] = true; });
const orphanSet = {};
(map.orphans || []).forEach(function(u){ orphanSet[canon(u)] = true; });
const minConf = (map.minConfidence !== undefined ? map.minConfidence : 0.6);
const maxPer = (map.maxPerPage !== undefined ? map.maxPerPage : 3);

const parsed = $input.first().json.output || {};
const sugg = parsed.suggestions || [];

const perSource = {};
const rows = [];
const today = $now.toFormat('yyyy-MM-dd');
for (let i=0;i<sugg.length;i++){
  const s = sugg[i];
  if(!s || !s.sourceUrl || !s.targetUrl || !s.anchorText) continue;
  const sc = canon(s.sourceUrl); const tc = canon(s.targetUrl);
  if(sc === tc) continue;
  if(!validSet[sc] || !validSet[tc]) continue;
  let conf = (typeof s.confidence === 'number') ? s.confidence : parseFloat(s.confidence);
  if(isNaN(conf)) conf = 0;
  if(conf < minConf) continue;
  if(!perSource[sc]) perSource[sc] = 0;
  if(perSource[sc] >= maxPer) continue;
  perSource[sc]++;
  rows.push({ json: {
    date: today,
    sourceUrl: s.sourceUrl,
    targetUrl: s.targetUrl,
    anchorText: s.anchorText,
    confidence: Math.round(conf * 100) / 100,
    reason: s.reason || '',
    alreadyLinked: existing[sc + '|' + tc] ? 'yes' : 'no',
    targetIsOrphan: orphanSet[tc] ? 'yes' : 'no',
    status: 'pending'
  }});
}
return rows;
